def _pp_iter_reference(iter_node: ast.AST) -> tuple[str, str] | None:
    """
    If ``iter_node`` iterates over a ``self.<module>`` submodule (directly or through a builtin wrapper such as
    ``enumerate(self.layers)`` or ``reversed(self.layers)``), return ``(self_reference, module_name)``, e.g.
    ``("self.layers", "layers")``. Otherwise return ``None``.
    """
    candidate = iter_node
    if isinstance(iter_node, ast.Call) and iter_node.args:
        candidate = iter_node.args[0]
    if _is_self_reference(candidate):
        return f"self.{candidate.attr}", candidate.attr
    return None


def _loop_variable_name(for_node: ast.For) -> str | None:
    """Return the name bound to the iterated module in a ``for`` loop, handling ``enumerate``-style unpacking."""
    target = for_node.target
    if isinstance(target, ast.Name):
        return target.id
    if isinstance(target, ast.Tuple):
        names = [element.id for element in target.elts if isinstance(element, ast.Name)]
        if names:
            # `for i, layer in enumerate(self.layers)` binds the module to the last element.
            return names[-1]
    return None


def trf011_check_pp_plan_attribute_access(
    tree: ast.Module, file_path: Path, source_lines: list[str], violations: list[Violation], rule_id: str
) -> list[Violation]:
    """
    Flag non-standard attribute accesses on submodules managed by the pipeline parallelism plan. Under pipeline
    parallelism such submodules may not be materialized on the current rank, so reaching into their custom
    attributes inside ``forward`` is unsafe.
    """
    pp_plan_modules = _PP_PLAN_MODULES_BY_MODEL_DIR
    if not pp_plan_modules:
        return violations

    model_dir = _model_dir_name(file_path)
    if model_dir is None:
        return violations

    pp_modules = pp_plan_modules.get(model_dir)
    if not pp_modules:
        return violations

    class_to_bases = _collect_class_bases(tree)
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        if not _inherits_pretrained_model(node.name, class_to_bases):
            continue

        forward_method = _class_methods(node).get("forward")
        if forward_method is None:
            continue

        # Case 1: loop over a PP-managed submodule, e.g. `for layer in self.layers: layer.<attr>`.
        for for_node in [sub for sub in ast.walk(forward_method) if isinstance(sub, ast.For)]:
            reference = _pp_iter_reference(for_node.iter)
            if reference is None:
                continue
            self_reference, module_name = reference
            if module_name not in pp_modules:
                continue
            loop_variable = _loop_variable_name(for_node)
            if loop_variable is None:
                continue

            for sub_node in ast.walk(for_node):
                if not (
                    isinstance(sub_node, ast.Attribute)
                    and isinstance(sub_node.value, ast.Name)
                    and sub_node.value.id == loop_variable
                ):
                    continue
                if sub_node.attr in _STANDARD_NN_MODULE_ATTRIBUTES:
                    continue
                if _has_rule_suppression(source_lines, rule_id, sub_node.lineno):
                    continue

                access_expression = f"{loop_variable}.{sub_node.attr}"
                violations.append(
                    Violation(
                        file_path=file_path,
                        line_number=sub_node.lineno,
                        rule_id=rule_id,
                        message=(
                            f"{rule_id}: `{access_expression}` accesses a non-standard attribute on submodule "
                            f"`{self_reference}`, which is managed by the pipeline parallelism plan and may not be "
                            "materialized on the current rank."
                        ),
                    )
                )

        # Case 2: direct access of the form `self.<pp_module>.<attr>`.
        for sub_node in ast.walk(forward_method):
            if not (isinstance(sub_node, ast.Attribute) and _is_self_reference(sub_node.value)):
                continue
            pp_module = sub_node.value.attr
            if pp_module not in pp_modules:
                continue
            if sub_node.attr in _STANDARD_NN_MODULE_ATTRIBUTES:
                continue
            if _has_rule_suppression(source_lines, rule_id, sub_node.lineno):
                continue

            access_chain = f"self.{pp_module}.{sub_node.attr}"
            violations.append(
                Violation(
                    file_path=file_path,
                    line_number=sub_node.lineno,
                    rule_id=rule_id,
                    message=(
                        f"{rule_id}: `{access_chain}` accesses a non-standard attribute on a submodule managed by "
                        "the pipeline parallelism plan and may not be materialized on the current rank."
                    ),
                )
            )

    return violations


